218	        // is safer.
219	        let Some((params, params_id)) = symbol.iter_parents().find_map(|p| {
220	            let params = p.kind().as_formal_parameters()?;
221	            Some((params, p.id()))
222	        }) else {
223	            debug_assert!(false, "FormalParameter should always have a parent FormalParameters");
