279	    /// `params_id` is the [`NodeId`] to a [`AstKind::FormalParameters`] node.
280	    ///
281	    /// The following allowed conditions are handled:
282	    /// 1. setter parameters - removing them causes a syntax error.
283	    /// 2. TS constructor property definitions - they declare class members.
284	    fn is_allowed_param_because_of_method<'a>(
285	        semantic: &Semantic<'a>,
286	        param: &FormalParameter<'a>,
287	        params_id: NodeId,
288	    ) -> bool {
289	        let mut parents_iter = semantic.nodes().ancestor_kinds(params_id);
290	
291	        // in function declarations, the parent immediately before the
292	        // FormalParameters is a TSDeclareBlock
293	        let Some(parent) = parents_iter.next() else {
294	            return false;
295	        };
296	        if matches!(parent, AstKind::Function(f) if f.r#type == FunctionType::TSDeclareFunction) {
297	            return true;
298	        }
299	
300	        // for non-overloads, the next parent will be the function
301	        let Some(maybe_method_or_fn) = parents_iter.next() else {
302	            return false;
303	        };
304	
305	        match maybe_method_or_fn {
306	            // arguments inside setters are allowed. Without them, the program
307	            // has invalid syntax
308	            AstKind::MethodDefinition(MethodDefinition {
309	                kind: MethodDefinitionKind::Set, ..
310	            })
311	            | AstKind::ObjectProperty(ObjectProperty { kind: PropertyKind::Set, .. }) => true,
312	
313	            // Allow unused parameters in function overloads
314	            AstKind::Function(f)
315	                if f.body.is_none() || f.r#type == FunctionType::TSDeclareFunction =>
316	            {
317	                true
318	            }
319	            // Allow unused parameters in method overloads and overrides
320	            AstKind::MethodDefinition(method)
321	                if method.value.r#type == FunctionType::TSEmptyBodyFunctionExpression
322	                    || method.r#override =>
323	            {
324	                true
325	            }
326	            // constructor property definitions are allowed because they declare
327	            // class members
328	            // e.g. `class Foo { constructor(public a) {} }`
329	            AstKind::MethodDefinition(method) if method.kind.is_constructor() => {
330	                param.has_modifier()
331	            }
332	            // parameters in abstract methods will never be directly used b/c
333	            // abstract methods have no bodies. However, since this establishes
334	            // an API contract and gets used by subclasses, it is allowed.
335	            AstKind::MethodDefinition(method) if method.r#type.is_abstract() => true,
336	            _ => false,
337	        }
338	    }
