343	    pub(super) fn is_allowed_binding_rest_element(symbol: &Symbol) -> bool {
344	        for parent in symbol.iter_parents() {
345	            // If this is a binding rest element that is part of a TS function parameter,
346	            // for example: `function foo(...messages: string[]) {}`, then we will allow it.
347	            if let AstKind::Function(f) = parent.kind() {
348	                return f.is_typescript_syntax();
349	            }
350	        }
351	
352	        false
353	    }
